HOSP = (0.2030, 35.1050)


def _h(s: str) -> float:  # deterministic 0..1
    h = 2166136261
    for c in s:
        h = ((h ^ ord(c)) * 16777619) & 0xFFFFFFFF
    h ^= h >> 15
    h = (h * 2246822507) & 0xFFFFFFFF
    h ^= h >> 13
    return (h % 10000) / 10000


