def q2_place_summary():
    rows = []
    tot24 = sum(s[3] for s in NANDI_SUBS); tot25 = sum(s[4] for s in NANDI_SUBS)
    rows.append(("county", "Nandi", None, None, sum(s[1] for s in NANDI_SUBS), 102000, tot24, tot25, 57.0))
    for s, v, p, a, b, f in NANDI_SUBS:
        rows.append(("sub", "Nandi", s, None, v, p, a, b, f))
    for s, w, v, p, a, b in NANDI_WARDS:
        rows.append(("ward", "Nandi", s, w, v, p, a, b, 57.0))
    for c, names in SUBL.items():
        v, p, age, fem, inj, acu, ncd, a, b = OTHER[c]
        wts = [0.3 + _h(c + n) for n in names]; t = sum(wts)
        rows.append(("county", c, None, None, v, p, a, b, fem))
        for n, wt in zip(names, wts):
            sh = wt / t
            rows.append(("sub", c, n, None, max(1, round(v * sh)), max(1, round(p * sh)), round(a * sh), round(b * sh), round(fem + (_h(n) - .5) * 9, 1)))
    for c, v in {"Kisii": 8, "Trans Nzoia": 9}.items():
        rows.append(("county", c, None, None, v, v, 4, 4, OTHER[c][3]))
    return pd.DataFrame(rows, columns=["level", "county", "sub_county", "ward", "visits", "unique_patients", "visits_2024", "visits_2025", "pct_female"])


def q2_category_by_place():
    rows = []
    sub_bias = {"Emgwen": 1.0, "Chesumei": 1.05, "Mosop": 0.95, "Nandi Hills": 1.0, "Aldai": 1.0, "Tindiret": 1.0, "Tinderet": 1.0}
    for s, w, v, p, a, b in NANDI_WARDS:
        area = a + b
        for cat, base in CATS.items():
            share = base * sub_bias.get(s, 1) * (0.6 + 0.9 * _h(w + cat))
            n = int(round(area * share / 100))
            if n > 0:
                rows.append(("Nandi", s, w, cat, n, area))
    for c, names in SUBL.items():
        v = OTHER[c][0]
        wts = [0.3 + _h(c + n) for n in names]; t = sum(wts)
        for n, wt in zip(names, wts):
            area = max(1, round(v * wt / t * 1.0))
            for cat, base in CATS.items():
                k = int(round(area * base * (0.5 + _h(n + cat)) / 100 * 4))
                if k > 0:
                    rows.append((c, n, "(none)", cat, min(k, area), area))
    return pd.DataFrame(rows, columns=["county", "sub_county", "ward", "category", "category_visits", "area_visits"])


def _offset(lat, lon, km, bearing):
    return lat + km * math.cos(bearing) / 111.0, lon + km * math.sin(bearing) / (111.0 * math.cos(math.radians(lat)))


def q2_locality_distance():
    names = [("Kapsabet", 0.6), ("Kamobo", 3), ("Chepterit", 7), ("Baraton", 5), ("Lessos", 12), ("Kipsigak", 9), ("Kaptel", 17), ("Kapkangani", 4),
             ("Kapsasur", 6), ("Kosirai", 15), ("Showground", 1.4), ("Surungai", 22), ("Meswo", 11), ("Mosobecho", 8), ("Kapyagan", 14), ("Kobujoi", 26),
             ("Nandi Hills Twp", 28), ("Kaplamai", 31), ("Ol'Lessos", 19), ("Chepkunyuk", 33), ("Kemeloi", 24), ("Kaptumo", 21)]
    rows = []
    for i, (n, km) in enumerate(names):
        la, lo = _offset(*HOSP, km, _h(n) * 6.283)
        for cat, mix in [("All visits", 1.0)] + [(c, 0.01 * v + 0.01) for c, v in CATS.items()]:
            base = 4000 / (1 + km * 0.9) + 20
            far = 1 + (BAND_MIX.get(cat, BAND_MIX["All visits"])[3] / 8 if km > 10 else 0) * (1.6 if cat in ("Injury & trauma", "Maternal & obstetric", "Mental health", "Malaria") and km > 5 else 1)
            v = int(base * (mix if cat != "All visits" else 1) * far * (0.7 + 0.6 * _h(n + cat)))
            if v >= 5:
                rows.append((n, "ward", "sub", "Nandi", la, lo, round(km, 2), cat, v))
    for c, (v, *_rest) in OTHER.items():
        km = KM[c]
        la, lo = _offset(*HOSP, km, _h(c) * 6.283)
        for cat in ["All visits", "Injury & trauma", "Infectious disease", "NCD"]:
            n = int(v * (1 if cat == "All visits" else 0.2))
            if n >= 5:
                rows.append((f"{c} (county)", "", "", c, la, lo, float(km), cat, n))
    return pd.DataFrame(rows, columns=["locality", "ward", "sub_county", "county", "latitude", "longitude", "km", "category", "visits"])


def q2_other_county_distance():
    rows = []
    for c, (v, p, age, fem, inj, acu, ncd, a, b) in OTHER.items():
        rows.append((c, v, p, inj, acu, ncd, KM[c]))
    rows.append(("Baringo", 12, 9, 2, 3, 1, None))  # a county with no located centre: still shown, labelled "distance n/a"
    return pd.DataFrame(rows, columns=["county", "visits", "unique_patients", "injury_visits", "acute_illness_visits", "ncd_visits", "km_from_hospital"])


def q2_locality_growth():
    d = [("Emgwen", "Kapsabet", 32023, 49462), ("Chesumei", "Kamobo", 3638, 725), ("Chesumei", "Chepterit", 2501, 372), ("Aldai", "Baraton", 1881, 309),
         ("Nandi Hills", "Lessos", 1736, 384), ("Mosop", "Kipsigak", 1696, 376), ("Chesumei", "Kaptel", 1624, 316), ("Emgwen", "Kapkangani", 1571, 317),
         ("Mosop", "Kapsasur", 1455, 347), ("Chesumei", "Kosirai", 1223, 232), ("Emgwen", "Showground", 1332, 107), ("Mosop", "Surungai", 1037, 260)]
    rows = []
    for s, n, a, b in d:
        sh24 = 100 * a / sum(x[2] for x in d if x[0] == s)
        sh25 = 100 * b / sum(x[3] for x in d if x[0] == s)
        rows.append((s, n, a, b, int(a * .6), int(b * .6), sh24, sh25, int(a * .12), int(b * .1)))
    return pd.DataFrame(rows, columns=["sub_county", "locality", "visits_2024", "visits_2025", "patients_2024", "patients_2025", "share_sub_2024", "share_sub_2025", "new_patients_2024", "new_patients_2025"])


