def q3_gonococcal():
    rows = []
    spec = {2023: 142, 2024: 1468, 2025: 768, 2026: 93}
    share = {"Adolescent (<18)": (0.125, 0.4), "Youth (18-24)": (0.25, 0.28), "Young Adult (25-34)": (0.33, 0.32), "Adult (35-44)": (0.17, 0.14), "Middle Age (45-54)": (0.08, 0.06), "55+": (0.04, 0.03)}
    for yr, tot in spec.items():
        for g, (fs, ms) in share.items():
            fv = round(tot * 0.7 * fs / sum(v[0] for v in share.values()))
            mv = round(tot * 0.3 * ms / sum(v[1] for v in share.values()))
            if yr == 2024 and g == "Adolescent (<18)":
                fv, mv = 112, 71
            if yr == 2024 and g == "Young Adult (25-34)":
                fv = 329
            for sx, v in (("F", fv), ("M", mv)):
                sep = 13 if (yr == 2024 and g == "Young Adult (25-34)" and sx == "F") else 0
                preg = round(v * 0.03) if sx == "F" and g in ("Youth (18-24)", "Young Adult (25-34)") else 0
                rows.append((yr, sx, g, v, preg, 0, sep, 0, round(v * 0.97), v - round(v * 0.97), round(v * 100 / tot, 1)))
    return pd.DataFrame(rows, columns=["visit_year", "sex", "age_group", "visits", "with_pregnancy", "with_pid", "with_sepsis", "with_hiv", "from_nandi", "from_outside_nandi", "pct_of_year"])


