def _q4_with_geo(text: str) -> pd.DataFrame:
    """Join the ward results to ward geolocation the way the real query does (ward + sub-county), as lat / lon / BOUNDARY_GEOJSON."""
    import json as _json
    df = _csv(text)
    lat, lon, gj = [], [], []
    for w, s in zip(df.ward, df.sub_county):
        g = _Q4_WARD_GEO.get(f"{w}|{s}")
        if g is None:
            lat.append(None), lon.append(None), gj.append(None)
        else:
            lat.append(g[0]), lon.append(g[1])
            gj.append(_json.dumps({"type": "Polygon", "coordinates": [g[2]]}) if g[2] else _json.dumps({"type": "Point", "coordinates": [g[1], g[0]]}))
    df["latitude"], df["longitude"], df["boundary_geojson"] = lat, lon, gj
    return df


def q4_ward_patients():
    return _q4_with_geo(_Q4_WARD_PATIENTS)


def q4_ward_recurrent():
    return _q4_with_geo(_Q4_WARD_RECURRENT)

