def q6_wards():
    """Ward counts joined to the same simplified ward geometry as Tab 5 (same wards, same boundaries)."""
    df = _csv(_Q6_WARDS)
    df['latitude'] = [(_Q5_WARD_GEO.get(f'{w}|{s}') or [None])[0] for w, s in zip(df.ward, df.sub_county)]
    df['longitude'] = [(_Q5_WARD_GEO.get(f'{w}|{s}') or [None, None])[1] for w, s in zip(df.ward, df.sub_county)]
    df['boundary_geojson'] = [(_Q5_WARD_GEO.get(f'{w}|{s}') or [None, None, None])[2] for w, s in zip(df.ward, df.sub_county)]
    return df

